/* TOKEN WATCH - an agentic p0pc0rn app: the new tokens that ROSE most since they launched in the last hour, on the chains you pick
   (Avalanche to start; Solana, Base, Ethereum, BNB Chain and Arbitrum too, up to 3 at a time), only tokens on a real DEX pool: a token
   still on a launchpad's bonding curve is never shown. The host looks them up (the source tokens.dexscreener: GeckoTerminal's new pools
   and DEX Screener's launch signals to find them, every number from DEX Screener) and ranks them in code: launched within the hour, on a
   DEX pool with at least $5,000 of liquidity, risen since launch, biggest rise first, the top 5, with what GoPlus (EVM chains) or
   RugCheck (Solana) report on each. Juli writes two plain sentences on each and one summary from the facts the
   app gives her ("In the last hour on Avalanche ..."), in small bites, after you close the app; her words are kept only when every
   number is in the facts and nothing in them sounds like advice, else the app's own words are used. Every summary ends with "Not
   financial advice. New tokens are very high risk and many are scams." It says "rose most since launch", never "best", has no buy,
   sell or swap button, and gives no advice of any kind. Safety: it only relays what GoPlus and RugCheck report ("GoPlus reports ...");
   p0pc0rn takes no responsibility for security or safety, and Juli checks no contract (SAFETY, shown where the flags are).
   Watch closely (a button here, or "watch closely" in Juli's chat): every 15 minutes while p0pc0rn is open, a note in Juli's chat only
   when a new token enters the top 5 or a safety flag changes; it stops by itself after 2 hours, or when p0pc0rn closes, and says so.
   The five parts of an agentic app (Skeleton Guide, "Two kinds of app"):
     goal      manifest.goal: tell me which new tokens rose most since they launched, on the chains I pick
     notebook  K.notebook('tokens'): grounding = the last look (its top 5 and their numbers, what launched on each chain); suspected =
               Juli's sentences and summary for that look; the chains you picked and Watch closely stay in K.save
     tasks     active (the open app): pick chains, look (each chain at most every 5 minutes), look back 6 hours, open a token on DEX
               Screener, watch closely. idle (checks): 'write' (Juli's words for the last look), 'watch' (Watch closely), 'tidy'
     reach     tokens.dexscreener (read only), chain.snowtrace (an Avalanche token's contract, only at the person's tap, once per token),
               Juli (permissions.juli ["ask", "big"]) with her watch-tokens skill, the Bigger brain for name references (its own switch,
               off until the person turns it on), Juli's chat (chat.post)
     review    the list itself: it only tells you; nothing happens on its own.
   Everything it keeps stays on this phone. */
// ===== CORE (pure: no p5, no p0, no K: node-tested as it ships, v39/tests/tokenwatch/core.test.mjs) =====
// The person's chains, the numbers as people read them, the facts Juli may use, the app's own words, the check that keeps Juli's words
// plain and grounded, the summary, the "nothing launched" path and Watch closely's schedule and what it posts.
const TW = (() => {
  const CHAINS = { avalanche: 'Avalanche', solana: 'Solana', base: 'Base', ethereum: 'Ethereum', bsc: 'BNB Chain', arbitrum: 'Arbitrum' };
  const IDS = Object.keys(CHAINS), MAX = 3, DEFAULT = ['avalanche'], FLOOR = 5000, GAP_MIN = 5;
  const WATCH = { everyMin: 15, forMin: 120 };
  const NOTE = 'Not financial advice. New tokens are very high risk and many are scams.';
  // Josh (Nov 1), shown where the flags are, in Watch closely's panel and at the foot of the app
  const SAFETY = 'p0pc0rn takes no responsibility for security or safety. It only relays the information GoPlus, RugCheck and Routescan report. Juli does not check contracts and cannot provide any safety information.';
  const clip = (s, n) => String(s == null ? '' : s).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
  const and = (l) => { l = l.filter(Boolean); return l.length <= 1 ? l.join('') : l.slice(0, -1).join(', ') + ' and ' + l[l.length - 1]; };
  const plural = (n, w, ws) => `${n} ${n === 1 ? w : ws || w + 's'}`;
  const fnv = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619) >>> 0; return h.toString(36); };

  // ---- the chains the person picks (Avalanche on until they turn it off by hand; up to 3)
  /** saved -> the chains, in the order offered; nothing saved yet -> Avalanche; [] stays [] (the person turned every one off) */
  function chainsOf(saved) {
    if (!Array.isArray(saved)) return DEFAULT.slice();
    const want = new Set(saved.map((x) => String(x)));
    return IDS.filter((c) => want.has(c)).slice(0, MAX);
  }
  /** a tap on a chain -> {list, msg}: on -> off always; off -> on while fewer than 3 are on */
  function toggle(list, id) {
    const L = chainsOf(list); if (!CHAINS[id]) return { list: L, msg: '' };
    if (L.includes(id)) return { list: L.filter((c) => c !== id), msg: '' };
    if (L.length >= MAX) return { list: L, msg: `Up to ${MAX} chains at a time: turn one off first.` };
    return { list: chainsOf(L.concat(id)), msg: '' };
  }
  const chainText = (list) => and((list || []).map((c) => CHAINS[c] || c));
  const windowText = (hours) => (hours === 6 ? 'the last 6 hours' : 'the last hour');

  // ---- numbers as people read them (the same strings go into the facts Juli's words are checked against)
  function usd(n) {
    if (n == null || !Number.isFinite(n) || n < 0) return 'unknown';
    if (n < 1000) return '$' + Math.round(n).toLocaleString('en-US');
    if (n < 1e6) { const p = 10 ** (Math.floor(Math.log10(n)) - 2); return '$' + (Math.round(n / p) * p).toLocaleString('en-US'); }
    if (n < 1e9) return '$' + String(Number((n / 1e6).toFixed(n < 1e7 ? 2 : 1))) + ' million';
    return '$' + String(Number((n / 1e9).toFixed(2))) + ' billion';
  }
  function pctText(p) {
    const a = Math.abs(+p || 0);
    return (a >= 100 ? Math.round(a).toLocaleString('en-US') : a >= 10 ? String(Math.round(a)) : String(Number(a.toFixed(1)))) + ' %';
  }
  const moveText = (p) => (!Number.isFinite(+p) ? 'unknown' : +p > 0 ? 'up ' + pctText(p) : +p < 0 ? 'down ' + pctText(p) : 'flat');
  function ageText(min) {
    if (min == null || !Number.isFinite(+min)) return 'an unknown time';
    const m = Math.max(0, Math.round(+min));
    if (m < 1) return 'under a minute';
    if (m < 60) return plural(m, 'minute');
    const h = Math.floor(m / 60), r = m % 60;
    return r ? `${plural(h, 'hour')} ${plural(r, 'minute')}` : plural(h, 'hour');
  }
  const short = (a) => { const s = String(a || ''); return s.length > 12 ? s.slice(0, 6) + '…' + s.slice(-4) : s; };
  const keyOf = (t) => (t ? t.chain + ':' + t.address : '');
  /** what a safety source REPORTS, plainly (p0pc0rn only relays it; a check that found nothing says only that, never "safe") */
  function safetyText(s) {
    if (!s || s.status !== 'checked') return 'Safety check unavailable';
    const n = (s.flags || []).length;
    return n ? `${s.by} reports: ${and(s.flags.map((f) => f.text))}` : `${s.by} reports none of the flags it checks (that is not a guarantee)`;
  }

  // ---- Routescan (Snowtrace's API, Avalanche tokens only, Josh Nov 1): ONE check per token, only at the person's tap ("Check on
  // Snowtrace"), kept with the token and never asked again: its holder count, whether its contract's source is verified, and how many of
  // its newest transactions failed. FAIL = the red flag: at least 10 failed AND at least 20 % of the newest ones (100 at most); said as
  // what Routescan shows, never as a verdict
  const FAIL = { min: 10, share: 0.2 };
  const RS_PARTS = ['holders', 'verified', 'txs'];
  const nn = (v) => (v != null && v !== '' && Number.isFinite(+v) && +v >= 0 ? Math.floor(+v) : null);
  /** the parts of the check still to ask for (none once all three came back: the kept answer is final) */
  const rsMissing = (kept) => RS_PARTS.filter((x) => !((kept && kept.done) || []).includes(x));
  /** the kept answer + what the host's chain.snowtrace op 'token' sent back (r.done = the parts it answered) -> the new kept answer, or
   *  the old one when nothing new came (a part already kept is never replaced) */
  function rsMerge(kept, r, at) {
    const o = Object.assign({ holders: null, verified: null, recent: null, failed: null, done: [] }, kept || {}), done = new Set(o.done || []);
    const got = new Set(((r && r.done) || []).filter((x) => RS_PARTS.includes(x)));
    if (got.has('holders') && !done.has('holders')) { o.holders = nn(r.holders); done.add('holders'); }
    if (got.has('verified') && !done.has('verified')) { o.verified = r.verified === true ? true : r.verified === false ? false : null; done.add('verified'); }
    if (got.has('txs') && !done.has('txs')) { const n = nn(r.recent) || 0; o.recent = Math.min(100, n); o.failed = Math.min(o.recent, nn(r.failed) || 0); done.add('txs'); }
    if (done.size === ((kept && kept.done) || []).length) return kept || null;
    o.done = RS_PARTS.filter((x) => done.has(x)); o.at = +at || 0;
    return o;
  }
  /** a kept answer -> {text, failedLine, flagged, done} (text '' = nothing to say yet), or null (nothing kept) */
  function rsOf(rs) {
    if (!rs) return null;
    const parts = [];
    if (nn(rs.holders) != null) parts.push(`${nn(rs.holders).toLocaleString('en-US')} ${nn(rs.holders) === 1 ? 'holder' : 'holders'}`);
    if (rs.verified === true || rs.verified === false) parts.push(rs.verified ? 'its contract is verified on Snowtrace' : 'its contract is not verified on Snowtrace');
    const recent = nn(rs.recent) || 0, failed = Math.min(recent, nn(rs.failed) || 0), flagged = recent > 0 && failed >= FAIL.min && failed / recent >= FAIL.share;
    const done = !rsMissing(rs).length;
    return { text: parts.length ? 'Routescan reports ' + and(parts) : done ? 'Routescan has no holder count or source for this contract' : '',
      failedLine: flagged ? `Routescan shows ${failed} of the last ${recent} transactions failed` : '', flagged, done };
  }

  // ---- the facts for one token: every word and number Juli may use
  function factsOf(t, i) {
    const mv = (t && t.move) || {}, s = (t && t.safety) || {}, tx = ((t && t.txns) || {}).h1 || {}, vol = ((t && t.volume) || {}).h1;
    return {
      n: (i || 0) + 1, symbol: clip(t.symbol, 14) || short(t.address), name: clip(t.name, 32), chain: CHAINS[t.chain] || t.chain,
      age: ageText(t.ageMin), move: moveText(mv.pct), since: mv.since === 'graduation' ? 'since it graduated' : 'since launch', up: +mv.pct > 0,
      grad: t.status === 'graduated' ? (t.pump ? 'a pump.fun-style launch' : `a ${clip(t.curve, 24) || 'launchpad'} launch`) : '', liquidity: usd(t.liquidity), volume: usd(vol),
      value: t.fdv ? 'an FDV of ' + usd(t.fdv) : t.marketCap ? 'a market cap of ' + usd(t.marketCap) : '',
      buys: Math.max(0, Math.round(+tx.buys || 0)), sells: Math.max(0, Math.round(+tx.sells || 0)),
      safety: safetyText(s), by: s.by || '', checked: s.status === 'checked', flags: s.status === 'checked' ? (s.flags || []).map((f) => f.text) : [],
      notes: (t.flags || []).map((f) => f.text), score: s.score != null ? `${s.score} of 100` : '', lp: s.lpLockedPct != null ? `${s.lpLockedPct} %` : '',
      rs: t.rs ? [rsOf(t.rs).text, rsOf(t.rs).failedLine].filter(Boolean).join('; ') : '',   // only a kept answer (the person's tap)
    };
  }
  /** the facts as lines (the prompt, and the digest that tells Juli's words for these numbers apart) */
  function factLines(f) {
    const L = [`${f.symbol}${f.name && f.name !== f.symbol ? ' (' + f.name + ')' : ''} on ${f.chain}: launched ${f.age} ago${f.grad ? ', graduated from ' + f.grad : ''}, ${f.move} ${f.since}`,
      `liquidity ${f.liquidity}; volume in the last hour ${f.volume}; ${f.buys} buys and ${f.sells} sells in the last hour${f.value ? '; ' + f.value : ''}`,
      `safety: ${f.safety}${f.score ? '; RugCheck risk score ' + f.score : ''}${f.lp ? '; liquidity locked ' + f.lp : ''}${f.rs ? '; ' + f.rs : ''}`];
    if (f.notes.length) L.push('also: ' + f.notes.join('; '));
    return L;
  }
  const digest = (f) => fnv(factLines(Object.assign({}, f, { rs: '' })).join('|'));   // a Snowtrace answer tapped later keeps Juli's words
  /** the app's own two sentences (shown when Juli's are not there, or did not pass the checks) */
  function sentences(f) {
    return `${f.symbol}${f.name && f.name !== f.symbol ? ' (' + f.name + ')' : ''} launched on ${f.chain} ${f.age} ago${f.grad ? `, graduated from ${f.grad},` : ''} and is ${f.move} ${f.since}. ` +
      `It has ${f.liquidity} in liquidity and ${f.volume} in volume in the last hour, with ${f.buys} buys and ${f.sells} sells${f.value ? ', and ' + f.value : ''}.`;
  }
  /** Juli's question for one token: the facts as lines, then the rules (her watch-tokens skill adds her know-how) */
  function tokenPrompt(f) {
    return `Facts from DEX Screener about a new token on ${f.chain}:\n` + factLines(f).map((l) => '- ' + l).join('\n') +
      '\n\nWrite exactly 2 short, plain sentences about this token: when it launched, how much it rose and since when (as written above), its liquidity and its trading. ' +
      'Use the name, numbers and words exactly as written above, and no other numbers. A safety flag only as "GoPlus reports ...", "RugCheck reports ..." or "Routescan reports ...". ' +
      'Describe only: no advice of any kind (never buy, sell, hold or invest, never what anyone should do), no predictions, no opinions, never "best"; ' +
      'never say a token is safe, unsafe, secure, audited or legit, and never say that you checked it. No other text.';
  }

  // ---- the summary (code ranks; Juli only words it)
  function lookFacts(look) {
    const rows = (look && look.rows) || [], chains = (look && look.chains) || [], st = (look && look.stats) || {};
    const per = chains.map((c) => { const s = st[c] || {}; return { chain: CHAINS[c] || c, kept: s.kept || 0, launched: s.launched || 0, below: s.floorOut || 0, curve: s.curve || 0, down: s.down || 0, status: s.status || 'ok' }; });
    const list = rows.map((t, i) => factsOf(t, i));
    return { window: windowText(look && look.hours), hours: look && look.hours === 6 ? 6 : 1, chains: chainText(chains), floor: usd(FLOOR),
      count: per.reduce((a, p) => a + p.kept, 0), shown: list.length, flaggedN: list.filter((f) => f.flags.length).length, uncheckedN: list.filter((f) => !f.checked).length, tokens: list.map((f) => ({ symbol: f.symbol, chain: f.chain, move: f.move, since: f.since, liquidity: f.liquidity, by: f.by, flags: f.flags.length, flagged: f.flags.slice(0, 2), checked: f.checked })),
      quiet: per.filter((p) => !p.kept && p.status !== 'error' && p.status !== 'soon').map((p) => ({ chain: p.chain, below: p.below })),
      failed: per.filter((p) => p.status === 'error').map((p) => p.chain) };
  }
  /** the chains with nothing to show -> [{chain, label, why, curve, below, down, unchecked}] ("say so plainly"): why 'none' (nothing
   *  launched), 'filtered' (some launched, none on a DEX pool with enough liquidity and risen), 'error', 'soon' */
  function emptyChains(look) {
    const st = (look && look.stats) || {};
    return ((look && look.chains) || []).map((c) => ({ chain: c, label: CHAINS[c] || c, s: st[c] || {} }))
      .filter((x) => !(x.s.kept > 0)).map((x) => ({ chain: x.chain, label: x.label, curve: x.s.curve || 0, below: x.s.floorOut || 0, down: x.s.down || 0, unchecked: x.s.unchecked || 0,
        why: x.s.status === 'error' ? 'error' : x.s.status === 'soon' ? 'soon' : x.s.launched || x.s.curve || x.s.unchecked ? 'filtered' : 'none' }));
  }
  /** one chain with nothing, in plain words */
  function emptyLine(e, hours) {
    const w = windowText(hours);
    if (e.why === 'error') return `${e.label}: DEX Screener or GeckoTerminal did not answer this time.`;
    if (e.why === 'soon') return `${e.label}: looked less than ${GAP_MIN} minutes ago.`;
    if (e.why === 'filtered') {
      const parts = [e.curve ? `${e.curve} still on a bonding curve` : '', e.below ? `${e.below} under ${usd(FLOOR)}` : '', e.down ? `${e.down} down since launch` : '',
        e.unchecked ? `${e.unchecked} not checked this time (p0pc0rn’s cap of 12 requests a look)` : ''].filter(Boolean);
      return `Nothing on ${e.label} in ${w} rose on a DEX pool with at least ${usd(FLOOR)} in liquidity${parts.length ? ` (${and(parts)})` : ''}.`;
    }
    return `Nothing launched on ${e.label} in ${w} that DEX Screener lists.`;
  }
  /** the app's own summary (Juli's replaces it when it passes the checks); never ends without NOTE (withNote) */
  function summaryText(look) {
    const F = lookFacts(look), T = F.tokens, out = [];
    if (!T.length) {
      out.push(`In ${F.window} on ${F.chains}, no new token rose on a DEX pool with at least ${F.floor} in liquidity.`);
      return out.join(' ');
    }
    out.push(`In ${F.window} on ${F.chains}, ${plural(F.count, 'new token')} on a DEX pool with at least ${F.floor} in liquidity rose since launch.`);
    const multi = (look.chains || []).length > 1, on = (x) => (multi ? ` on ${x.chain}` : '');
    const rest = T.slice(1, 3).map((x) => `${x.symbol}${on(x)} (${x.move})`);
    out.push(`${T.length === 1 ? 'It is' : 'The biggest rise is'} ${T[0].symbol}${on(T[0])}, ${T[0].move} ${T[0].since}${rest.length ? `; then ${and(rest)}` : ''}.`);
    const fl = T.filter((x) => x.flags > 0).length, un = T.filter((x) => !x.checked).length;
    if (fl) out.push(`GoPlus or RugCheck report safety flags for ${fl === T.length ? (T.length === 1 ? 'it' : `all ${T.length}`) : `${fl} of the ${T.length}`}.`);
    if (un) out.push(`The safety check was unavailable for ${un === T.length && T.length > 1 ? `all ${T.length}` : plural(un, 'of them', 'of them').replace(/^1 of them$/, 'one of them')}.`);
    for (const q of F.quiet) out.push(`Nothing on ${q.chain} rose on a DEX pool with that much liquidity.`);
    return out.join(' ');
  }
  /** Juli's question for the summary */
  function summaryPrompt(look) {
    const F = lookFacts(look), start = `In ${F.window} on ${F.chains}`;
    const lines = [`${F.count} new tokens on a DEX pool with at least ${F.floor} in liquidity rose since launch`].concat(
      F.tokens.map((x, i) => `${i + 1}. ${x.symbol} on ${x.chain}: ${x.move} ${x.since}; liquidity ${x.liquidity}; ${x.checked ? (x.flags ? `${x.by} reports: ` + x.flagged.join('; ') : `${x.by} reports no safety flags`) : 'safety check unavailable'}`),
      F.quiet.map((q) => `${q.chain}: nothing rose on a DEX pool with at least ${F.floor} in liquidity`));
    return `Facts from DEX Screener about new tokens in ${F.window} on ${F.chains}, ranked by how much they rose:\n` + lines.map((l) => '- ' + l).join('\n') +
      `\n\nWrite ONE short paragraph of 2 to 4 sentences. Start with "${start}". Say how many rose, which rose most and by how much, and what GoPlus or RugCheck report (as "GoPlus reports ..." or "RugCheck reports ..."). ` +
      'Use the names, numbers and words exactly as written above, and no other numbers. Describe only: no advice of any kind (never buy, sell, hold or invest, never what anyone should do), ' +
      'no predictions, no opinions, never "best", never call a token good or bad; never say a token is safe, unsafe, secure, audited or legit, and never say that you checked it. No other text.';
  }
  const withNote = (s) => { const t = clip(s, 1200); return t.includes(NOTE) ? t : (t ? t + ' ' : '') + NOTE; };

  // ---- Juli's words, kept only when they are plain facts: no advice words, every number in the facts, no name the facts do not have
  // the counts and taxes ARE the data ("120 buys and 80 sells", "a sell tax of 25 %"): those nouns are set aside before the advice check
  const NOUNS = [/\b\d[\d,]*\s+(?:buys|sells)\b/gi, /\bbuys and(?:\s+\d[\d,]*)?\s+sells\b/gi, /\b(?:buy|sell) tax(?:es)?\b/gi];
  const ADVICE = /\b(?:buy|buys|buying|bought|sell|sells|selling|sold|hold|holding|hodl\w*|invest\w*|moon\w*|gems?|ape[sd]?|aping|opportunit\w*|should|shouldn['’]?t|must|ought|recommend\w*|suggest\w*|advi[cs]\w*|price targets?|target price|guarantee\w*|\d+\s?x|profit\w*|gains?|best|top picks?|safe|safer|safest|unsafe|risk[- ]free|undervalued|cheap|bargain|potential|promising|bullish|bearish|dump\w*|worth|fomo|next big|explod\w*|skyrocket\w*|soar\w*|rocket\w*|lambo|legit\w*|trustworth\w*|solid|healthy|scam\w*|rug(?!check)\w*|secur\w*|audit\w*|verified|no[- ]risks?|low[- ]risks?|harmless|protected)\b|\bpump(?!\.fun|['’])\w*|\bdon['’]?t miss\b|\bget in\b/i;
  // Josh (Nov 1): Juli checks no contract and cannot give safety information: never "I checked", and a safety source only as what it reports
  const CHECKED = /\b(?:I|we|Juli)\s+(?:have\s+|has\s+|just\s+)?(?:checked|verified|reviewed|audited|scanned|analy[sz]ed|inspected)\b|\bchecked by (?:me|Juli)\b/i;
  const REPORTS = /\b(?:GoPlus|RugCheck|Routescan)\b(?!\s+(?:reports?|shows?)\b|\s+(?:or|and)\s+(?:GoPlus|RugCheck|Routescan)\s+reports?\b)/;
  const OKW = new Set(['DEX', 'Screener', 'GeckoTerminal', 'GoPlus', 'Security', 'RugCheck', 'Routescan', 'Snowtrace', 'CoinGecko', 'FDV', 'EVM', 'USD', 'In', 'The', 'It', 'Its', 'It’s', "It's", 'This', 'That',
    'These', 'Those', 'They', 'Their', 'There', 'Since', 'With', 'And', 'But', 'Also', 'Both', 'A', 'An', 'Of', 'On', 'At', 'Over', 'Within', 'About', 'After', 'Before',
    'During', 'From', 'For', 'To', 'By', 'As', 'Meanwhile', 'Overall', 'Most', 'Only', 'Just', 'All', 'Each', 'Every', 'Some', 'Among', 'Another', 'Other', 'Nothing',
    'None', 'No', 'Not', 'One', 'Two', 'Three', 'Four', 'Five', 'First', 'Second', 'Third', 'Then', 'Next', 'Its', 'Safety', 'Flags', 'I', 'AM', 'PM'].concat(Object.values(CHAINS), ['BNB', 'Chain']));
  const COMMON = new Set(['launched', 'trading', 'liquidity', 'volume', 'safety', 'flags', 'none', 'nothing', 'overall', 'meanwhile', 'also', 'its', 'it', 'they', 'there',
    'these', 'this', 'that', 'the', 'a', 'an', 'in', 'on', 'at', 'since', 'with', 'and', 'but', 'both', 'each', 'every', 'some', 'all', 'most', 'only', 'just', 'over',
    'within', 'about', 'after', 'before', 'during', 'from', 'for', 'of', 'to', 'by', 'as', 'then', 'next', 'among', 'another', 'other', 'no', 'not', 'one', 'two',
    'three', 'four', 'five', 'first', 'second', 'third', 'in', 'buyers', 'sellers', 'trades', 'price', 'prices']);
  function unknownNames(line, factsText) {
    const s = String(line), low = factsText.toLowerCase(), out = new Set(), re = /[A-Z][\p{L}\p{N}.$_+’'-]*[\p{L}\p{N}]|[A-Z]/gu;
    let m;
    while ((m = re.exec(s))) {
      const w = m[0]; if (OKW.has(w) || factsText.includes(w)) continue;
      const before = s.slice(0, m.index), first = !before.trim() || /[.!?:;–—]\s*$/.test(before);
      if (first && (COMMON.has(w.toLowerCase()) || low.includes(w.toLowerCase()))) continue;
      out.add(w);
    }
    return [...out];
  }
  /** the fact phrases a line may quote as they are (a flag's own words, a token's name), set aside before the advice check */
  function scrub(s, facts) {
