// ===== IDLE TASK 1: write (Juli's words for the last look, right after the person closes the app; at most one summary a look) =====
async function juliToken(t, i, ctx, per) {
  const f = TW.factsOf(withRs(t), i), d = TW.digest(f), k = TW.keyOf(t);   // a kept Snowtrace answer is a fact too (never asked for here)
  if (per[k] && per[k].d === d) return per[k].s;
  if (left(ctx) < 25) return '';
  try {
    const a = String(await within(K.ask(TW.tokenPrompt(f), { skill: SKILL }), (left(ctx) - 12) * 1000)).replace(/\s+/g, ' ').trim();
    const c = TW.checkWords(a, f, K.facts, 'token');
    if (c.ok) { per[k] = { d, s: c.line, at: Date.now() }; return c.line; }
    ctx.log(`Left out Juli’s words on ${f.symbol} (${c.why})`);
  } catch (e) { ctx.log(`Wrote ${f.symbol}’s lines itself (${whyNot(e)})`); if (e && (e.code === 'NOT_DOWNLOADED' || e.code === 'BUSY' || e.code === 'RATE_LIMIT')) throw e; }
  return '';
}
async function writeTask(ctx) {
