  const L = lookNow(), W = wordsNow();
  if (!L || !W || W.lookAt !== L.at || W.state !== 'waiting') return { active: false };
  if (Date.now() - L.at > 30 * 60e3) { nb.put('words', { data: Object.assign({}, W, { state: 'stale' }) }); return { active: false }; }   // old news is not posted
  const per = Object.assign({}, W.per || {});
  let stop = '';
  for (let i = 0; i < L.rows.length && !stop; i++) { if (left(ctx) < 30) break; try { await juliToken(L.rows[i], i, ctx, per); } catch (e) { stop = whyNot(e); } }
  let summary = '';
  if (!stop && left(ctx) >= 25) {
    const facts = TW.lookFacts(L);
    try {
      const a = String(await within(K.ask(TW.summaryPrompt(L), { skill: SKILL }), (left(ctx) - 12) * 1000)).replace(/\s+/g, ' ').trim();
      const c = TW.checkWords(a, facts, K.facts, 'summary');
      if (c.ok) summary = c.line; else ctx.log(`Left out Juli’s summary (${c.why})`);
    } catch (e) { stop = whyNot(e); }
  }
  if (stop) ctx.log(`Kept its own words this time (${stop})`);
  nb.put('words', { data: { lookAt: L.at, state: 'done', summary, per, at: Date.now() }, evidence: [{ source: 'DEX Screener', at: L.at }].concat(summary ? [{ source: 'Juli, from those numbers', at: Date.now() }] : []) });
  if (summary) {   // Juli summarises the look in her chat (once a look)
    const F = TW.lookFacts(L), flagged = F.tokens.some((x) => x.flags > 0);
    const ok = await postNote({ title: `${TITLE} · ${F.window} on ${F.chains}`.slice(0, 80), severity: flagged ? 'watch' : 'info', text: TW.fit(summary, CREDIT_SHORT) });
