  const fl = flags.slice(0, 6).map((z) => ({ z, h: K.paraHeight(z.text, tw - 24, 'footnote', { maxLines: 2 }) + 6 }));
  const safeLine = s.status === 'checked' ? (s.flags && s.flags.length ? `${s.by} reports ${TW.plural(s.flags.length, 'flag')}` : `${s.by} reports none of the flags it checks (not a guarantee)`) + (s.score != null ? ` · risk score ${s.score} of 100` : '') : 'Safety check unavailable' + (s.why ? `: ${s.why}` : '');
  const rsh = (rsv && rsv.text ? K.paraHeight(rsv.text, tw - 24, 'footnote', { maxLines: 2 }) + 22 : 0) + (need.length ? 48 + (rsm ? K.paraHeight(rsm.text, tw, 'caption', { maxLines: 2 }) + 4 : 0) : 0);
  const ref = refOf(t), rl = ref && ref.status === 'yes' && ref.line ? ref : null;   // v4: a name reference (no clear one: nothing shown)
  const rfh = rl ? K.paraHeight(rl.line, tw - 24, 'footnote', { maxLines: 2 }) + (rl.cite ? 30 : 6) : 0;
  const h = 128 + 64 + 26 + rfh + rsh + fl.reduce((a, b) => a + b.h, 0) + 8 + wh + 18 + 52;
  K.card(x, y, w, h, { r: 18 });
  const chip = TW.CHAINS[t.chain] || t.chain, cw = K.chipWidth(chip);
  K.text(`${i + 1}`, x + 16, y + 31, 'headline', K.C.text3);
  K.text(f.symbol, x + 38, y + 31, 'headline', K.C.text, { maxW: w - 70 - cw });
  K.chip(x + w - 16 - cw, y + 14, chip, { color: ACCENT });
  K.text(`${f.name && f.name !== f.symbol ? f.name + ' · ' : ''}launched ${f.age} ago`, x + 16, y + 54, 'subhead', K.C.text2, { maxW: tw });
  const mv = t.move || {}, up = +mv.pct >= 0;
  K.icon(up ? 'arrowUp' : 'arrowDown', x + 27, y + 88, 20, K.C.text);
  K.text(TW.pctText(mv.pct), x + 44, y + 97, 'title2', K.C.text, { maxW: tw - 120 });
  K.text(f.since, x + 44 + K.measure(TW.pctText(mv.pct), 'title2') + 8, y + 96, 'footnote', K.C.text2);
  // the numbers: liquidity, volume, FDV / market cap, buys and sells (all DEX Screener's)
  const cells = [['Liquidity', f.liquidity], ['Volume, last hour', f.volume], [t.fdv ? 'FDV' : 'Market cap', TW.usd(t.fdv || t.marketCap)], ['Buys / sells, last hour', `${f.buys} / ${f.sells}`]];
  const cw2 = tw / 2;
  cells.forEach((c, j) => { const cx = x + 16 + (j % 2) * cw2, cy = y + 120 + Math.floor(j / 2) * 34; K.text(c[0], cx, cy, 'caption', K.C.text3, { maxW: cw2 - 8 }); K.text(c[1], cx, cy + 17, 'subhead', K.C.text, { maxW: cw2 - 8 }); });
  let yy = y + 128 + 64;
  if (rl) {   // the line code wrote from the Bigger brain's checked answer, and its source (title, site, licence; the link opens under the app)
    K.icon('sparkle', x + 24, yy + 8, 13, K.C.text2); const ph = K.paraHeight(rl.line, tw - 24, 'footnote', { maxLines: 2 });
    K.para(rl.line, x + 38, yy, tw - 24, 'footnote', K.C.text, { maxLines: 2 }); yy += ph + 2;
    if (rl.cite) { const c = rl.cite, lab = `Source: ${c.title}${c.site ? ', ' + c.site : ''}${c.license ? ' · ' + c.license : ''}`.slice(0, 52);
      if (K.button('cite:' + k, x + 32, yy, tw - 16, 26, lab, { style: 'ghost', size: 12 })) { if (hasBig()) p0.juli.cite(c.id).catch(() => {}); } yy += 28; }
    else yy += 4;
  }
  K.icon(s.status === 'checked' ? 'shield' : 'alert', x + 24, yy + 7, 14, s.status === 'checked' ? K.C.text2 : K.C.warn);
  K.text(safeLine, x + 38, yy + 12, 'footnote', s.status === 'checked' ? K.C.text2 : K.C.warn, { maxW: tw - 22 }); yy += 26;
  if (rsv && rsv.text) {   // Routescan's kept answer (Avalanche): the button became this
    K.icon('shield', x + 24, yy + 8, 13, K.C.text2); const ph = K.paraHeight(rsv.text, tw - 24, 'footnote', { maxLines: 2 });
    K.para(rsv.text, x + 38, yy, tw - 24, 'footnote', K.C.text2, { maxLines: 2 }); K.text('Powered by Routescan.io APIs', x + 38, yy + ph + 10, 'caption', K.C.text3, { maxW: tw - 24 }); yy += ph + 22;
  }
  if (need.length) {   // not checked yet (or only part of it came back): one tap, once
    const busy = !!RS.busy[k], label = busy ? 'Checking on Snowtrace…' : need.length < TW.RS_PARTS.length ? 'Check the rest on Snowtrace' : 'Check on Snowtrace';
    if (K.button('rs:' + k, x + 16, yy + 2, tw, 38, label, { style: 'secondary', icon: 'shield', disabled: busy || !!rsm })) snowtraceTap(t);
    yy += 48;
    if (rsm) { const mh = K.paraHeight(rsm.text, tw, 'caption', { maxLines: 2 }); K.para(rsm.text, x + 16, yy - 4, tw, 'caption', K.C.warn, { maxLines: 2 }); yy += mh + 4; }
  }
  for (const g of fl) { K.icon(g.z.level === 'note' ? 'info' : 'alert', x + 24, yy + 8, 13, FLAG_COL(g.z.level)); K.para(g.z.text, x + 38, yy, tw - 24, 'footnote', K.C.text, { maxLines: 2 }); yy += g.h; }
  yy += 8;
  K.para(words, x + 16, yy, tw, 'footnote', K.C.text2, { maxLines: 5 }); yy += wh;
  K.text(mine ? 'Juli, from these numbers' : 'From these numbers', x + 16, yy + 12, 'caption', K.C.text3); yy += 18;
  if (K.button('open:' + k, x + 16, y + h - 48, tw, 38, 'Open on DEX Screener', { style: 'secondary', icon: 'chart', disabled: !t.pair })) openToken(t);
  return y + h;
}
